// Decide que esta publicado HOY.
//
// El indice es una FUNCION PURA del calendario y de la fecha: publicado es
// todo lo que tiene fecha <= hoy. No se guarda estado en ningun sitio, asi
// que el flujo se puede volver a lanzar las veces que haga falta y el
// resultado es siempre el mismo. Si guardase una lista de "ya publicados",
// cualquier fallo a medias dejaria el indice y el servidor descuadrados.

const cal = $input.first().json;
const arts = cal.articulos || [];

const hoy = new Date().toISOString().slice(0, 10);

const publicados = arts.filter(a => a.fecha <= hoy);
const pendientes = arts.filter(a => a.fecha > hoy);

// Los que hay que SUBIR en esta pasada: los que tocan hoy. Los anteriores ya
// estan arriba de pasadas previas, pero el indice y el sitemap se regeneran
// enteros de todas formas.
const nuevos = arts.filter(a => a.fecha === hoy);

return [{
  json: {
    hoy,
    nuevos,
    hay_nuevos: nuevos.length > 0,
    publicados,
    pendientes,
    total_publicados: publicados.length
  }
}];

// Reconstruye el indice y el sitemap ENTEROS desde el calendario.
//
// Se regeneran completos en cada pasada, no se van parcheando. Parchear un
// HTML con expresiones regulares funciona hasta el dia que no, y entonces el
// indice queda con una tarjeta duplicada o media etiqueta suelta y nadie se
// entera hasta semanas despues.

const d = $('¿Toca publicar algo?').first().json;
const tplIdx = $('Plantilla del índice').first().json.data;
const tplMap = $('Plantilla del sitemap').first().json.data;

const esc = s => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio',
               'agosto','septiembre','octubre','noviembre','diciembre'];
const enLetra = f => {
  const [a, m, dia] = f.split('-');
  return `${Number(dia)} de ${MESES[Number(m) - 1]} de ${a}`;
};

// --- Tarjetas ------------------------------------------------------------
// Los publicados van arriba, del mas nuevo al mas viejo. Los pendientes
// debajo, en orden de salida, y SIN enlace: un enlace que no lleva a ningun
// sitio gasta la confianza de quien lo pulsa.

const pub = [...d.publicados].sort((x, y) => y.fecha.localeCompare(x.fecha));
const pen = d.pendientes;

function tarjeta(a, publicado, destacado) {
  const clases = ['articulo-card'];
  if (!publicado) clases.push('articulo-card--pendiente');
  if (destacado) clases.push('articulo-card--destacado');
  clases.push('fade-in');

  const abre = publicado
    ? `<a href="${a.fichero}" class="${clases.join(' ')}">`
    : `<div class="${clases.join(' ')}">`;
  const cierra = publicado ? '</a>' : '</div>';

  const meta = publicado
    ? `<span>${enLetra(a.fecha)}</span>`
    : `<span class="articulo-card__estado">En camino</span>`;
  const pie = publicado ? 'Leer &rarr;' : 'Aún sin publicar';

  return `
          ${abre}
            <div class="articulo-card__cover articulo-card__cover--${a.variante}">
              <span class="articulo-card__num">${esc(a.tag)}</span>
              <span class="articulo-card__kicker">${esc(a.tag)}</span>
            </div>
            <div class="articulo-card__body">
              <div class="articulo-card__meta">${meta}</div>
              <h2 class="articulo-card__title">${esc(a.titulo)}</h2>
              <p class="articulo-card__text">${esc(a.entradilla)}</p>
              <span class="articulo-card__pie">${pie}</span>
            </div>
          ${cierra}`;
}

const tarjetas = [
  ...pub.map((a, i) => tarjeta(a, true, i === 0)),
  ...pen.map(a => tarjeta(a, false, pub.length === 0 && a === pen[0]))
].join('\n');

const indice = tplIdx.replace('<!--TARJETAS-->', tarjetas);

// --- Sitemap -------------------------------------------------------------
// Solo los publicados. Meter en el sitemap una URL que todavia no existe es
// pedirle a Google que rastree un 404.

const urls = pub.map(a => `  <url>
    <loc>https://alexperdel.com/articulos/${a.fichero}</loc>
    <lastmod>${a.fecha}</lastmod>
    <changefreq>monthly</changefreq>
    <priority>0.8</priority>
  </url>`).join('\n');

const sitemap = tplMap.replace('<!--ARTICULOS-->', urls);

return [{
  json: {
    resumen: `${pub.length} publicados, ${pen.length} pendientes`,
    nuevos: d.nuevos.map(a => a.titulo)
  },
  binary: {
    indice: {
      data: Buffer.from(indice, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    },
    sitemap: {
      data: Buffer.from(sitemap, 'utf8').toString('base64'),
      mimeType: 'application/xml',
      fileName: 'sitemap.xml'
    }
  }
}];
